    fetch("https://api.sleeper.app/v1/players/nfl", { headers: UA }).then(x => x.json()),
    fetch("https://api.sleeper.app/v1/stats/nfl/regular/" + season, { headers: UA }).then(x => x.ok ? x.json() : {}).catch(() => ({}))
