  const pos = {}, copy = new Map();
  rows.forEach((r, i) => { const n = r.slice(); n[1] = i + 1; pos[r[5]] = (pos[r[5]] || 0) + 1; n[2] = pos[r[5]]; copy.set(r, n); });
  for (const k in out) if (copy.has(out[k])) out[k] = copy.get(out[k]);
